ee:variables.ee:set-variable:
%dw 2.0 output application/json var entityCode = vars.runContext.entityCode default "ENT0091" var reportType = vars.runContext.reportType default "STR" var periodDateStr = (vars.runContext.periodEnd[0 to 9] replace "-" with "") default "20260911" var seqStr = (vars.runContext.sequenceNumber as Number) as String {format: "000"}
// Reliable unique run identifier to guarantee collision-free archival var runIdClean = ((vars.runContext.runId default ("RUN-" ++ (now() as String {format: "yyyyMMdd-HHmmss"}) ++ "-" ++ (uuid()[0 to 5]))) replace "RUN-" with "" replace ":" with "" replace "/" with "" replace "\\" with "" replace " " with "_")
var submissionFilename = entityCode ++ "_" ++ reportType ++ "_" ++ periodDateStr ++ "_" ++ seqStr ++ ".csv" var summaryFilename = entityCode ++ "_" ++ reportType ++ "_" ++ periodDateStr ++ "_" ++ seqStr ++ "_SUMMARY.txt"
var archiveSubmissionFilename = entityCode ++ "_" ++ reportType ++ "_" ++ periodDateStr ++ "_" ++ seqStr ++ "_" ++ runIdClean ++ ".csv" var archiveSummaryFilename = entityCode ++ "_" ++ reportType ++ "_" ++ periodDateStr ++ "_" ++ seqStr ++ "_" ++ runIdClean ++ "_SUMMARY.txt"
var outDir = p('directories.output') var arcDir = p('directories.archive') --- { submissionFilename: submissionFilename, summaryFilename: summaryFilename, archiveSubmissionFilename: archiveSubmissionFilename, archiveSummaryFilename: archiveSummaryFilename, outputSubmissionFilePath: outDir ++ "/" ++ submissionFilename, archiveSubmissionFilePath: arcDir ++ "/" ++ archiveSubmissionFilename, archiveSummaryFilePath: arcDir ++ "/" ++ archiveSummaryFilename }
